# slot), not here.\n##\n'), ('lines 601-605', 'const SIGNAL_CYCLE_S: float = 60.0\n## Each colour\'s window, seconds into the cycle, tiling it: green 33 s, amber\n## 4 s (MUTCD\'s yellow change interval is 3 to 6 s), red 23 s. Whole seconds,\n## so the boundary two windows share is one float in both.\nconst SIGNAL_WINDOWS_S: Dictionary = {"Green": [0.0, 33.0], "Amber": [33.0, 37.0], "Red": [37.0, 60.0]}\n', '## The whole cycle, and each colour\'s window in it for a head on the X half,\n## seconds, tiling it: green 18 s, amber 4 s (MUTCD\'s yellow change interval\n## is 3 to 6 s), red 26 s -- of which the last 2 s are the ALL-RED clearance,\n## while the other half\'s red has not yet ended. A Z head reads the same\n## windows half a cycle on (`SIGNAL_HALF_CYCLE_S`), so its green begins as\n## the X half\'s all-red ends. Whole seconds, so a boundary two windows share\n## is one float in both.\n##\n## 0.165.0 ran 60 s (green 33). The walker, walking cold run 9386, of a\n## junction they passed: "traffic lights done change?" -- measured, the\n## package\'s lenses carried the 0.165.0 clock, so the lights DID change, once\n## a minute, and a passer-by saw one state. 48 s keeps a real signal\'s order\n## and amber and changes within 24 s of anyone arriving. The green is the\n## taste knob: there is no physical number for how long a level\'s player\n## watches a corner.\nconst SIGNAL_CYCLE_S: float = 48.0\nconst SIGNAL_HALF_CYCLE_S: float = SIGNAL_CYCLE_S / 2.0\nconst SIGNAL_WINDOWS_S: Dictionary = {"Green": [0.0, 18.0], "Amber": [18.0, 22.0], "Red": [22.0, 48.0]}\n'), ('lines 618-618', 'uniform float cycle_s = 60.0;\n', 'uniform float cycle_s = 48.0;\nuniform float half_cycle_s = 24.0;\n'), ('lines 620-624', "uniform float lit_to_s = 0.0;\n\nvoid fragment() {\n\t// one clock for every signal: no instance term (the pass's notes)\n\tfloat t = mod(TIME, cycle_s);\n", "uniform float lit_to_s = 0.0;\n\n// which half of the cycle this head runs on: 0 facing along world X, 1 along Z\n// -- the node's own basis, so a junction's two directions take turns\nvarying float half_;\n\nvoid vertex() {\n\tvec3 face = MODEL_MATRIX[2].xyz;\n\thalf_ = step(abs(face.x), abs(face.z));\n}\n\nvoid fragment() {\n\t// one clock for every signal, its two directions half a cycle apart\n\tfloat t = mod(TIME + half_ * half_cycle_s, cycle_s);\n"), ('lines 1336-1337', '\tsm.set_shader_parameter("cycle_s", SIGNAL_CYCLE_S)\n\tvar w: Array = SIGNAL_WINDOWS_S[colour]\n', '\tsm.set_shader_parameter("cycle_s", SIGNAL_CYCLE_S)\n\tsm.set_shader_parameter("half_cycle_s", SIGNAL_HALF_CYCLE_S)\n\tvar w: Array = SIGNAL_WINDOWS_S[colour]\n')], 'tests/unit/test_worldskin_signal_lenses.py': [('lines 105-109', 'def test_every_signal_keeps_one_clock():\n    """No per-node term: every head at a junction faces the through road and\n    must show the same lens; the shutters\' and turning parts\' hash is the\n    opposite of what a signal needs."""\n    sh = _shader(_src())\n', 'def test_a_junction_s_two_directions_take_turns_on_one_clock():\n    """0.238.0: Lot faces every approach (0.128.0), so a head\'s FACING picks its\n    half of the cycle -- the node\'s own basis, never a hash or a position,\n    which would split one junction\'s heads apart. FAILS ON 0.237.0: one clock\n    and no half, so the side street and the main road went green together."""\n    src = _src()\n    sh = _shader(src)\n'), ('lines 111-111', '    assert "mod(TIME, cycle_s)" in sh\n', '    assert "MODEL_MATRIX[2]" in sh and "half_ = step(abs(face.x), abs(face.z));" in sh\n    assert "mod(TIME + half_ * half_cycle_s, cycle_s)" in sh\n    m = re.search(r"^const SIGNAL_HALF_CYCLE_S: float = SIGNAL_CYCLE_S / 2\\.0$", src, re.M)\n    assert m, "the half cycle is not half the cycle"\n    assert \'"half_cycle_s", SIGNAL_HALF_CYCLE_S\' in _func(src, "_signal_lens_material")\n\n\ndef test_the_two_halves_never_go_together_and_clear_on_all_red():\n    """At every instant at most one half shows green or amber, and each change\n    of right of way passes through a moment when both show red (the all-red\n    clearance) -- read off the windows the shader is given."""\n    src = _src()\n    cycle, wins = _cycle(src), _windows(src)\n    half = cycle / 2.0\n\n    def lit(t):\n        t %= cycle\n        return next(c for c, (a, b) in wins.items() if a <= t < b)\n\n    all_red = 0\n    for k in range(int(cycle * 4)):\n        t = k * 0.25\n        x, z = lit(t), lit(t + half)\n        assert not (x != "Red" and z != "Red"), (t, x, z)\n        all_red += x == "Red" and z == "Red"\n    assert all_red > 0, "no all-red clearance between the halves"\n\n\ndef test_a_passer_by_sees_a_change():\n    """The walker, walking cold run 9386: "traffic lights done change?" -- the\n    lights changed once a minute on 0.165.0\'s 60 s clock. Each half changes\n    within half the cycle, and the cycle is under a minute."""\n    cycle = _cycle(_src())\n    assert cycle < 60.0, cycle\n    assert _windows(_src())["Green"][1] <= cycle / 2.0\n')]}
NEW_FILES = {}
CHANGELOG = '## [0.238.0] - a junction\'s two directions take turns, and a passer-by sees them change\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 11): "traffic\nlights done change?" Measured on that package and on 9387\'s: every lens carried 0.165.0\'s clock (`cycle_s` 60, green\n0-33 s, amber 33-37, red 37-60), so the lights DID change -- once a minute, and someone walking past saw one state.\nAnd Lot 0.128.0 now faces every approach of a signalised junction (finding 12), so on 0.165.0\'s one clock the side\nstreet and the main road went green together: in cold run 9387\'s package, every head at the junction showed green in\nthe same frame.\n\n### Changed\n- **A head\'s facing picks its half of the cycle.** The lens shader reads the node\'s own basis in the vertex stage\n  (`MODEL_MATRIX[2]`, the axis both of Zoo\'s signal forms face along): heads facing along world X run on the clock,\n  heads facing along Z half a cycle later. A junction\'s two directions face perpendicular axes and the two ways along\n  one road face the same one, so a junction takes turns with no table of junctions; every junction still runs in step,\n  as a coordinated arterial does. Said in the pass\'s notes: a junction whose roads both lie near the diagonal to the\n  world\'s axes would put both directions on one half -- the grammars lay roads on the axes, and that gap is Lot\'s to\n  close if it opens.\n- **The cycle is 48 s**: green 18 s, amber 4 s (MUTCD\'s yellow change interval is 3 to 6 s), red 26 s, the last 2 s\n  of it the all-red clearance before the other half\'s green. Every head changes within 24 s of anyone arriving. The\n  green is the taste knob; there is no physical number for how long a player watches a corner.\n\n### Cost\n- None added: the same three lens surfaces a signal, the same materials, the same draws; a step and a few multiplies\n  more in the lens\'s vertex stage, six signals a junction pair.\n\n### Measured\n- On a copy of cold run 9387\'s walk copy with this import script swapped in and the signal module re-imported\n  (`[worldskin] ... 3 signal lens surface(s) given the junction\'s clock`), one station at the junction\'s corner (eye\n  36, 1.7, 9 -> 24, 4.6, 22, Godot), against the copy as shipped: as shipped every head green; with this the head\n  facing the other axis red while the two on the right are green (the factory\'s\n  `patches/lf_signal_opposition/heads_shipped_over_trial.png`, `corner_*.webp`). The shader compiles and draws.\n\n### Tests\n- `tests/unit/test_worldskin_signal_lenses.py`: the halves by facing (the node\'s basis, never a hash or a position),\n  the two halves never green or amber together with an all-red moment between them, a change within half a cycle and\n  a cycle under a minute -- all three failing on 0.237.0, the second at t = 0 with both halves green.\n\n'
OLD_VERSION, NEW_VERSION = '0.237.0', '0.238.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
